"""mpl_toolkits.axes_grid1.parasite_axes — parasite axes."""

from matplotlib.axes._axes import Axes


class ParasiteAxesBase:
    pass


class ParasiteAxes(Axes, ParasiteAxesBase):
    name = 'parasite_axes'

    def __init__(self, parent_axes, **kwargs):
        super().__init__(getattr(parent_axes, 'figure', None), **kwargs)
        self._parent_axes = parent_axes


class HostAxesBase:
    """Mixin that gives an Axes the ability to host overlay
    ParasiteAxes that share its transform. ``parasites`` is the live
    list of registered parasites."""

    def __init__(self):
        self.parasites = []

    def get_aux_axes(self, tr=None, viewlim_mode=None, axes_class=None):
        """Create a new ParasiteAxes that shares this host's transform
        (``tr`` overrides the data transform when given)."""
        para = ParasiteAxes(self)
        para._aux_trans = tr
        para._viewlim_mode = viewlim_mode
        self.parasites.append(para)
        return para

    def twin(self, aux_trans=None, axes_class=None):
        para = ParasiteAxes(self)
        para._aux_trans = aux_trans
        self.parasites.append(para)
        return para

    def twinx(self):
        """Standard matplotlib twinx — secondary y-axis on the right."""
        para = ParasiteAxes(self)
        para._secondary_axis = 'y'   # tag for downstream layout logic
        self.parasites.append(para)
        return para

    def twiny(self):
        """Secondary x-axis on the top."""
        para = ParasiteAxes(self)
        para._secondary_axis = 'x'
        self.parasites.append(para)
        return para

    def get_parasites(self):
        return list(self.parasites)


class HostAxes(Axes, HostAxesBase):
    def __init__(self, *args, **kwargs):
        Axes.__init__(self, *args, **kwargs)
        HostAxesBase.__init__(self)


def host_subplot_class_factory(axes_class=None):
    return HostAxes

def host_axes_class_factory(axes_class=None):
    return HostAxes

def host_subplot(*args, **kwargs):
    return HostAxes(*args, **kwargs)

def host_axes(*args, **kwargs):
    return HostAxes(*args, **kwargs)


# ─── Added: SubplotHost + parasite_axes_class_factory ───────────────


from matplotlib.axes._axes import Axes


def parasite_axes_class_factory(axes_class=None):
    """Synthesise a parasite-axes class that shares its host's
    coordinates but maintains its own ticks/labels. ``axes_class`` is
    the base Axes class to derive from; defaults to :class:`Axes`."""

    if axes_class is None:
        axes_class = Axes
    class _ParasiteAxes(axes_class):
        """Auto-generated parasite axes — shares its host's data
        transform but has independent tick formatters."""
        def __init__(self, host, *args, **kwargs):
            super().__init__(host.figure if hasattr(host, 'figure') else None,
                              *args, **kwargs)
            self._host = host
    _ParasiteAxes.__name__ = f'Parasite{axes_class.__name__}'
    return _ParasiteAxes


class SubplotHost(Axes):
    """Host axes that can have :class:`ParasiteAxes` overlaid on top.
    The host owns the figure region; parasites borrow its transform.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._parasites = []

    def get_aux_axes(self, tr=None, viewlim_mode='equal', axes_class=None):
        Cls = parasite_axes_class_factory(axes_class)
        para = Cls(self)
        self._parasites.append(para)
        return para

    def parasites(self):
        return list(self._parasites)
